*{box-sizing:border-box} :root{--gold:#d5ad68;--gold-bright:#f4d28d;--ink:#090b0e;--panel:#11151a;--line:rgba(222,193,137,.2);--muted:#93949a;--red:#bd5756;--green:#73bd8d} html,body,#game-shell{margin:0;width:100%;height:100%;overflow:hidden;background:#090b0e;color:#f1eee8;font-family:Inter,Arial,sans-serif;touch-action:manipulation}button{font:inherit;color:inherit;border:0;cursor:pointer;-webkit-tap-highlight-color:transparent}#game-shell{position:relative;isolation:isolate}#world{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 42%,#35302a 0,#171719 40%,#090b0e 100%);z-index:-3}#world canvas{display:block;width:100%;height:100%}.vignette{position:absolute;inset:0;pointer-events:none;z-index:-2;background:linear-gradient(180deg,rgba(5,7,9,.58),transparent 25%,transparent 62%,rgba(5,7,9,.74)),radial-gradient(ellipse at center,transparent 42%,rgba(4,5,7,.35) 100%)}.topbar{position:absolute;inset:env(safe-area-inset-top,0) 0 auto;min-height:64px;display:flex;align-items:center;padding:11px clamp(14px,4vw,36px);gap:10px;z-index:5;background:linear-gradient(180deg,rgba(7,9,11,.83),rgba(7,9,11,.15));}.brand{display:flex;align-items:center;gap:10px;margin-right:auto}.brand-mark{width:37px;height:37px;border:1px solid #a68a58;color:var(--gold-bright);display:grid;place-items:center;transform:rotate(45deg);font-size:20px;text-shadow:0 0 12px #ddb96b}.brand-title{font:700 18px Cinzel,serif;letter-spacing:1.6px}.brand-title em{color:var(--gold-bright);font-style:normal}.brand-subtitle{font:600 8px Inter,sans-serif;letter-spacing:3.5px;color:#b1a58f;margin-top:1px}.icon-button,.profile-button{height:36px;border:1px solid rgba(220,190,135,.25);background:rgba(15,17,20,.78);color:#d7c6a4}.icon-button{width:38px;border-radius:4px;font-size:19px}.profile-button{display:flex;align-items:center;gap:8px;padding:0 10px;border-radius:3px;font-size:10px;font-weight:700;letter-spacing:.6px}.profile-button b{display:grid;place-items:center;width:22px;height:22px;background:#655330;color:#ffe0a2;border:1px solid #d5ad68;border-radius:50%;font:700 12px Cinzel}.profile-icon{font-size:17px;color:var(--gold)}.combat-hud{position:absolute;top:76px;left:clamp(14px,4vw,38px);right:clamp(14px,4vw,38px);z-index:3;display:grid;grid-template-columns:1fr minmax(210px,310px);grid-template-rows:auto auto;gap:15px;align-items:start;pointer-events:none}.location{display:flex;align-items:center;gap:9px;color:#f3e7d0;text-shadow:0 2px 6px #000}.location-icon{font-size:22px;color:var(--gold)}.location strong{font:600 11px Cinzel,serif;letter-spacing:1px}.location small{display:block;color:#a8a39a;font-size:8px;letter-spacing:1.5px;margin-top:3px}.target-card{background:linear-gradient(110deg,rgba(12,13,16,.91),rgba(19,18,18,.74));border:1px solid rgba(189,87,86,.45);padding:10px 12px 8px;box-shadow:0 8px 22px #0008;min-height:69px}.target-heading,.target-meta,.player-name-row,.xp-row{display:flex;justify-content:space-between;align-items:center}.target-heading{font:700 9px Inter,sans-serif;letter-spacing:1px}.target-heading span:last-child{font-size:8px;color:#c5b99f}.bar{height:6px;background:#29282a;overflow:hidden;border-radius:1px}.enemy-bar{margin:8px 0 5px;height:7px}.enemy-bar i,.hp-bar i,.xp-bar i{display:block;width:100%;height:100%;transition:width .25s ease}.enemy-bar i{background:linear-gradient(90deg,#862f35,#d75e54);box-shadow:0 0 9px #b84242}.target-meta{color:#8e8d8a;font-size:8px}.target-meta span:last-child{letter-spacing:1px}.player-bars{grid-column:1;grid-row:2;max-width:380px}.player-line{display:flex;gap:9px;align-items:center}.portrait{width:32px;height:32px;display:grid;place-items:center;background:linear-gradient(135deg,#4c3b25,#181716);border:1px solid #a58753;color:#f0d7a2;font-size:20px;box-shadow:0 0 13px #d5ad6830}.player-data{flex:1}.player-name-row{font-size:8px;letter-spacing:.7px;margin-bottom:5px;text-shadow:0 1px 5px #000}.player-name-row span{color:#e2d9cb;font-size:9px}.hp-bar{height:8px;border:1px solid #090