-height:24px;color:#e0bf79;text-shadow:0 0 12px currentColor}.sweep-icon{color:#a990dc}.heal-icon{color:#9bc995}.ult-icon{color:#e88463}.skill-label{font-size:7px;font-weight:800;line-height:9px;text-align:center;letter-spacing:.4px}.skill-button small{position:absolute;right:6px;top:4px;font-size:8px;color:#d0c3a9}.skill-button .cooldown{position:absolute;inset:auto 0 0;height:0;background:rgba(5,7,9,.75);transition:height .2s}.skill-button.ultimate{border-color:#ad704d}.skill-button.unavailable{filter:grayscale(.8);opacity:.62}.bottom-nav{position:absolute;z-index:4;left:0;right:0;bottom:0;padding:7px max(10px,env(safe-area-inset-left)) max(8px,env(safe-area-inset-bottom));min-height:67px;display:flex;justify-content:space-around;align-items:center;background:linear-gradient(0deg,rgba(7,9,11,.98),rgba(12,14,16,.94));border-top:1px solid rgba(205,176,120,.2)}.nav-item{position:relative;width:20%;height:50px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:3px;background:transparent;color:#777a7b}.nav-item span{font-size:20px;line-height:24px}.nav-item small{font-size:8px;letter-spacing:1px;font-weight:700}.nav-item.active{color:var(--gold-bright)}.nav-item.active:before{content:"";position:absolute;top:-8px;width:25px;height:2px;background:var(--gold-bright);box-shadow:0 0 9px #ddbb78}.nav-dot{display:none;position:absolute;width:6px;height:6px;top:8px;right:26%;border-radius:50%;background:#e5a84e}.nav-dot.show{display:block}.toast{position:absolute;z-index:12;top:19%;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:#171816ee;border:1px solid #d5ad68;color:#eadbbd;padding:10px 16px;font-size:11px;box-shadow:0 8px 30px #0008;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.panel-wrap,.modal-wrap{position:absolute;inset:0;z-index:10;display:none;align-items:flex-end;justify-content:center}.panel-wrap.open,.modal-wrap.open{display:flex}.panel-backdrop{position:absolute;inset:0;background:rgba(0,0,0,.62);backdrop-filter:blur(4px)}.game-panel{position:relative;width:min(690px,100%);max-height:min(78vh,740px);overflow:auto;background:linear-gradient(145deg,#191a1b,#101215 70%);border:1px solid rgba(212,177,106,.35);border-bottom:0;box-shadow:0 -16px 70px #000b;padding:22px clamp(18px,5vw,36px) max(26px,env(safe-area-inset-bottom));animation:rise .23s ease}@keyframes rise{from{transform:translateY(50px);opacity:.4}to{transform:translateY(0);opacity:1}}.panel-head{display:flex;align-items:flex-start;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:17px}.eyebrow{font-size:8px;color:var(--gold);letter-spacing:2px;font-weight:700}.panel-head h2{font:600 23px Cinzel,serif;margin:4px 0 0}.close-button{width:32px;height:32px;background:#242525;border:1px solid #4d473b;color:#d4c29d;font-size:19px}.panel-body{font-size:12px;color:#d7d2c8}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.stat-card,.item-card,.skill-card,.class-card,.dungeon-card,.rank-card{background:linear-gradient(135deg,#1d2022,#141619);border:1px solid #373735;padding:12px}.stat-card small{display:block;color:#92928c;font-size:8px;letter-spacing:1px;text-transform:uppercase}.stat-card strong{display:block;font:600 18px Cinzel,serif;color:#f0dfbb;margin-top:6px}.section-title{font:600 13px Cinzel,serif;color:#ead6aa;margin:19px 0 9px}.attribute-row,.equipment-row,.item-row,.skill-row,.rank-row{display:flex;align-items:center;justify-content:space-between;gap:10px;border-bottom:1px solid #ffffff0d;padding:10px 2px}.attribute-row:last-child,.equipment-row:last-child,.item-row:last-child{border-bottom:0}.attribute-name{color:#d0c6b5;font-weight:600}.attribute-name small{display:block;color:#85847f;font-size:9px;font-weight:400;margin-top:2px}.attribute-value{color:#e8d4a9;font-weight:700}.small-button,.action-button,.class-card button{background:linear-gradient(180deg,#9d804c,#64502f);border:1px solid #c5a568;color:#fff4d8;font-size:10px;font-weight:800;letter-spacing:.7px;padding:9px 12px}.small-button:disabled,.action-button:disabled{opacity:.42}.action-button{width:100%;margin-top:13px;padding:13px}.inline-actions{display:flex;gap:8px}.inline-actions>*{flex:1}.rarity-common{color:#e7e5df}.rarity-uncommon{color:#84d18b}.rarity-rare{color:#77b7ff}.rarity-epic{color:#c496ee}.rarity-legendary{color:#ffae60}.rarity-mythic{color:#ff6667}.rarity-divine{color:#ffe27d}.item-card{display:flex;align-items:center;gap:12px;margin:8px 0}.item-glyph{width:36px;height:36px;display:grid;place-items:center;background:#2c2a25;border:1px solid currentColor;font-size:18px}.item-info{flex:1}.item-info strong{display:block;font-size:11px}.item-info small{color:#9a978e;font-size:9px}.item-stat{font-size:9px;color:#bdb29e}.empty-state{text-align:center;padding:30px;color:#8e8b82;border:1px dashed #44413b;margin:10px 0}.skill-grid,.class-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.skill-card h3,.class-card h3{margin:0 0 5px;font:600 13px Cinzel,serif;color:#e9d8b4}.skill-card p,.class-card p{color:#9c9b96;font-size:10px;line-height:1.5;margin:0 0 8px}.skill-card small{color:#c3a56a;font-size:9px}.class-card{min-height:115px}.class-card.locked{opacity:.7}.class-card button{padding:7px;margin-top:6px}.rank-card{position:relative;display:flex;align-items:center;gap:14px;margin:12px 0}.rank-emblem{width:58px;height:58px;display:grid;place-items:center;border:1px solid #c4a35e;color:#f3d48f;font:700 28px Cinzel,serif;background:radial-gradient(circle,#51432b,#171819);clip-path:polygon(50% 0,91% 19%,100% 53%,75% 100%,25% 100%,0 53%,9% 19%)}.rank-card h3{font:600 14px Cinzel,serif;margin:0}.rank-card p{font-size:10px;color:#9a9992;margin:5px 0}.rank-progress{height:5px;background:#2c2d2b;margin-top:9px}.rank-progress i{height:100%;display:block;background:linear-gradient(90deg,#897044,#e8ca85)}.note{padding:10px;background:#262116;border-left:2px solid #bb9654;color:#c5b99e;font-size:10px;line-height:1.5;margin-top:12px}.dungeon-card{display:flex;gap:12px;align-items:center;margin:9px 0}.dungeon-art{width:65px;height:65px;flex:0 0 65px;background:radial-gradient(circle at 50% 70%,#615039,#1b1b1b 65%);display:grid;place-items:center;font-size:27px;color:#d0b071}.dungeon-info{flex:1}.dungeon-info h3{font:600 13px Cinzel,serif;margin:0 0 5px}.dungeon-info p{color:#9b9990;font-size:9px;margin:0;line-height:1.5}.modal-wrap{align-items:center;padding:20px}.modal-card{position:relative;width:min(420px,100%);background:linear-gradient(145deg,#1e1e1d,#111315);border:1px solid #c7a263;padding:26px 22px;text-align:center;box-shadow:0 20px 70px #000}.modal-icon{font-size:40px;color:#e5c27e;text-shadow:0 0 20px #c4944c;margin-bottom:7px}.modal-card h2{font:600 22px Cinzel,serif;margin:0 0 8px}.modal-card p{font-size:11px;color:#aaa69b;line-height:1.6}.reward-list{display:flex;justify-content:center;gap:18px;margin:18px 0;color:#e8d8b5;font-size:12px}.reward-list strong{color:#efc86e}.loading{position:absolute;inset:0;z-index:20;background:#090b0e;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;transition:opacity .7s}.loading.done{opacity:0;pointer-events:none}.loader-mark{color:#e3bd72;font-size:38px;animation:pulse 1.4s infinite}@keyframes pulse{50%{transform:scale(1.2);text-shadow:0 0 25px #eac878}}.loading strong{font:600 12px Cinzel,serif;letter-spacing:2px}.loading span{font-size:8px;color:#9b8b68;letter-spacing:3px}
@media(min-width:760px){.combat-hud{top:86px}.player-bars{max-width:430px}.skill-dock{bottom:95px;left:50%;right:auto;transform:translateX(-50%)}.skill-button{width:72px;height:84px}.bottom-nav{left:50%;right:auto;transform:translateX(-50%);width:min(560px,90%);border:1px solid #cdb07830;border-bottom:0}.game-panel{border-bottom:1px solid rgba(212,177,106,.35);margin-bottom:20px}.panel-wrap{align-items:center}.game-panel{border-bottom:1px solid rgba(212,177,106,.35)}}
@media(max-width:520px){.combat-hud{top:67px;grid-template-columns:1fr 1.08fr;gap:9px}.location strong{font-size:9px}.location small{font-size:7px}.target-card{padding:8px 9px;min-height:63px}.target-heading{font-size:8px}.player-bars{grid-column:1/-1;max-width:82%;margin-top:-1px}.currency{top:76px;right:0}.skill-dock{right:12px;bottom:96px;gap:6px}.skill-button{width:58px;height:71px}.skill-icon{font-size:19px;line-height:21px}.skill-label{font-size:6px;line-height:8px}.skill-button small{font-size:7px;top:3px;right:4px}.bottom-nav{min-height:62px}.nav-item{height:45px}.brand-title{font-size:16px}.topbar{min-height:56px;padding-top:8px}.profile-button{font-size:9px}.stat-grid{grid-template-columns:repeat(2,1fr)}.panel-head h2{font-size:20px}.game-panel{max-height:82vh;padding-top:18px}.currency{top:auto;bottom:169px}.combat-feedback{top:43%}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const SAVE_KEY='rank-up-awakening-v1';
const RANKS=['F','E','D','C','B','A','S','SS','SSS'];
const CLASS_PATHS={WARRIOR:['Knight','Paladin','Warrior King'],ASSASSIN:['Shadow','Reaper','Shadow Lord'],MAGE:['Sorcerer','Archmage','Arcane Master'],NECROMANCER:['Summoner','Master of the Dead','Undead Sovereign']};
const RARITIES=[['Common','#e7e5df',1],['Uncommon','#84d18b',1.18],['Rare','#77b7ff',1.42],['Epic','#c496ee',1.8],['Legendary','#ffae60',2.3],['Mythic','#ff6667',3.1],['Divine','#ffe27d',4.4]];
const ENEMY_DEFS={skeleton:{name:'Skeleton Warrior',type:'UNDEAD',hp:62,attack:7,defense:1,xp:28,gold:14,drop:.14,color:0xb5b3a5},goblin:{name:'Goblin',type:'CAVE FIEND',hp:48,attack:9,defense:0,xp:25,gold:19,drop:.18,color:0x77964d},dark:{name:'Dark Creature',type:'ABERRATION',hp:92,attack:12,defense:3,xp:44,gold:27,drop:.2,color:0x544e70},boss:{name:'Skeleton King',type:'DUNGEON BOSS',hp:440,attack:18,defense:5,xp:210,gold:160,drop:.85,color:0xd5bc84,boss:true}};
const SLOT_NAMES={weapon:'Weapon',helmet:'Helmet',chest:'Chest Armor',gloves:'Gloves',boots:'Boots',necklace:'Necklace',ring:'Ring'};
const GEAR_ICONS={weapon:'⚔',helmet:'⛑',chest:'♜',gloves:'♧',boots:'◢',necklace:'◉',ring:'◌'};
const freshState=()=>({level:1,xp:0,gold:120,rank:'F',attributes:{strength:5,agility:5,vitality:5,intelligence:5},attributePoints:0,classKey:null,classLevel:0,unlockedClasses:[],kills:0,bossKills:0,completedDungeons:[],dungeon:'Forgotten Catacombs',floor:1,gear:{weapon:null,helmet:null,chest:null,gloves:null,boots:null,necklace:null,ring:null},inventory:[],skillLevels:{strike:1,sweep:1,heal:1,ultimate:1},lastSeen:Date.now(),sound:true});
function loadState(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));if(!s)return freshState();const d=freshState();return {...d,...s,attributes:{...d.attributes,...s.attributes},gear:{...d.gear,...s.gear},skillLevels:{...d.skillLevels,...s.skillLevels}}}catch{return freshState()}}
let state=loadState(),lastTimestamp=Date.now(),elapsed=0,enemyList=[],target=null,worldScene,renderer,camera,clock,player,weaponPivot,enemyMeshes=[],effects=[],toastTimer,autoSaveTimer=0,attackTimer=0,enemySpawnTimer=0,respawnTimer=0,combatRunning=true,bossCue=false;
const cooldowns={strike:0,sweep:0,heal:0,ultimate:0},cooldownMax={strike:8,sweep:12,heal:18,ultimate:40};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];

function init3D(){
 const host=$('#world');worldScene=new THREE.Scene();worldScene.background=new THREE.Color(0x100f10);worldScene.fog=new THREE.FogExp2(0x100f10,.043);
 camera=new THREE.PerspectiveCamera(49,innerWidth/innerHeight,.1,80);camera.position.set(0,5.1,8.9);camera.lookAt(0,1.1,0);
 renderer=new THREE.WebGLRenderer({antialias:innerWidth>700,alpha:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;host.appendChild(renderer.domElement);
 worldScene.add(new THREE.HemisphereLight(0x918e98,0x211c19,1.55));const key=new THREE.DirectionalLight(0xffdfae,2.1);key.position.set(-4,8,6);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-9;key.shadow.camera.right=9;key.shadow.camera.top=9;key.shadow.camera.bottom=-9;worldScene.add(key);
 const cold=new THREE.PointLight(0x7087bc,18,14,2);cold.position.set(0,3,-4);worldScene.add(cold);
 makeDungeon();player=makeHunter();worldScene.add(player);player.position.set(0,0,2.3);
 clock=new THREE.Clock();window.addEventListener('resize',resize3D);renderer.setAnimationLoop(renderFrame);
}
function mat(color,roughness=.78,metalness=.05){return new THREE.MeshStandardMaterial({color,roughness,metalness})}
function box(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function makeDungeon(){
 const floorMat=mat(0x393631),stoneA=mat(0x4a4640),stoneB=mat(0x302f2e),darkStone=mat(0x262525),torchMat=new THREE.MeshStandardMaterial({color:0xff9a42,emissive:0xff5e13,emissiveIntensity:2});
 const floor=new THREE.Mesh(new THREE.PlaneGeometry(22,28),floorMat);floor.rotation.x=-Math.PI/2;floor.position.set(0,-.08,-3);floor.receiveShadow=true;worldScene.add(floor);
 for(let z=-15;z<9;z+=2.15)for(let x=-7.6;x<=7.6;x+=2.15){let tile=box(worldScene,x,-.035,z,2.08,.08,2.08,Math.random()>.4?stoneA:stoneB);tile.position.y=-.035;}
 // corridor walls and repeated heavy columns
 box(worldScene,-8.7,2,-3,1,4,27,darkStone);box(worldScene,8.7,2,-3,1,4,27,darkStone);
 for(const side of [-1,1])for(let z=-14;z<8;z+=5){box(worldScene,side*7.35,1.7,z,.95,3.4,1.15,stoneA);box(worldScene,side*7.35,3.5,z,.0+1.35,.35,1.55,stoneB);}
 box(worldScene,0,4.2,-16,18,.65,1.2,stoneB);box(worldScene,0,3.5,-16,9,.5,.5,stoneA);
 // carved stone ribs, altar debris, and brazier flames
 for(const side of [-1,1])for(let z=-12;z<8;z+=5){const flame=new THREE.Mesh(new THREE.IcosahedronGeometry(.15,1),torchMat);flame.position.set(side*6.2,2.15,z);worldScene.add(flame);const light=new THREE.PointLight(0xff8134,18,6,2);light.position.set(side*6.2,2.3,z);worldScene.add(light);box(worldScene,side*6.2,1.35,z,.26,.7,.26,stoneB);}
 for(let i=0;i<11;i++){const rubble=box(worldScene,(Math.random()-.5)*12,.12,-13+Math.random()*18,.18+Math.random()*.38,.25,.22+Math.random()*.4,stoneA);rubble.rotation.y=Math.random()*2;}
 // distant archway sigil
 const gate=new THREE.Mesh(new THREE.TorusGeometry(1.3,.07,8,32),new THREE.MeshStandardMaterial({color:0x756242,metalness:.65,roughness:.4,emissive:0x372710}));gate.position.set(0,2.8,-14.5);worldScene.add(gate);
}
