function maxHp(){return 100+state.attributes.vitality*12+state.level*8+gearStat('vitality')*10}
function attackPower(){return 8+state.attributes.strength*2+state.level*2+gearStat('attack')}
function defense(){return Math.floor(state.attributes.vitality*.6+state.attributes.agility*.22+gearStat('defense'))}
function gearStat(key){return Object.values(state.gear).reduce((n,item)=>n+(item?.stats?.[key]||0),0)}
function critChance(){return Math.min(45,5+state.attributes.agility*.45+gearStat('crit'))}
function xpNeeded(){return Math.floor(100*Math.pow(state.level,1.42))}
function xpPercent(){return Math.max(0,Math.min(1,state.xp/xpNeeded()))}
function formatNum(n){return Math.floor(n).toLocaleString()}
function updateHud(){
 const d=target?.userData,def=d&&ENEMY_DEFS[d.type];$('#header-level').textContent=`LVL ${String(state.level).padStart(2,'0')}`;$('#level-label').textContent=`LEVEL ${state.level}`;$('#hp-label').textContent=`${formatNum(playerHp)} / ${formatNum(maxHp())}`;$('#player-hp-fill').style.width=`${Math.max(0,playerHp/maxHp()*100)}%`;$('#xp-fill').style.width=`${xpPercent()*100}%`;$('#xp-label').textContent=`${formatNum(state.xp)} / ${formatNum(xpNeeded())} XP`;$('#gold-label').textContent=formatNum(state.gold);
 if(d&&def&&!d.dead){$('#enemy-name').textContent=def.name.toUpperCase();$('#enemy-level').textContent=`LVL ${Math.max(1,state.level)}`;$('#enemy-hp-text').textContent=`${formatNum(d.hp)} / ${formatNum(d.maxHp)}`;$('#enemy-hp-fill').style.width=`${Math.max(0,d.hp/d.maxHp*100)}%`;$('#enemy-type').textContent=def.type;$('#target-card').classList.toggle('boss-target',d.type==='boss');}else{$('#enemy-name').textContent='SCOUTING FOR PREY';$('#enemy-level').textContent='—';$('#enemy-hp-text').textContent='';$('#enemy-hp-fill').style.width='0%';$('#enemy-type').textContent='';}
}
let playerHp=100;
function gainXp(amount){state.xp+=amount;let levels=0;while(state.xp>=xpNeeded()){state.xp-=xpNeeded();state.level++;state.attributePoints+=3;playerHp=maxHp();levels++;}if(levels){notify(`LEVEL UP · LEVEL ${state.level}`);soundEffect(660,.18);if(state.level>=3&&!state.unlockedClasses.length)notify('CLASS QUEST AVAILABLE · OPEN CLASS SELECTION');}}
function notify(text){const node=$('#toast');node.textContent=text;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),2300)}
function feedback(text){const n=$('#combat-feedback');n.textContent=text;n.classList.remove('show');void n.offsetWidth;n.classList.add('show')}
function soundEffect(freq=440,duration=.08){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!window._audio)window._audio=new C();const ctx=window._audio,o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+duration)}catch{}}
function save(){try{state.lastSeen=Date.now();localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){console.warn('Save failed',e)}}
function rankRequirement(index){return [1,5,10,18,28,40,55,70,90][index]}
function makeItem(slot,forceRarity){const ri=forceRarity??(Math.random()<.008?6:Math.random()<.06?3:Math.random()<.27?2:Math.random()<.48?1:0),r=RARITIES[ri],power=Math.max(1,Math.floor((state.level+1)*r[2]*(.75+Math.random()*.55)));const choices=slot==='weapon'?{attack:power*2,crit:ri>1?Math.floor(power/2):0}:slot==='ring'||slot==='necklace'?{attack:power,crit:Math.floor(power/2)}:{defense:power,vitality:ri>1?Math.ceil(power/2):0};return{id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,slot,name:`${r[0]} ${slot==='weapon'?'Catacomb Blade':SLOT_NAMES[slot]}`,rarity:r[0],rarityIndex:ri,stats:choices,level:state.level,upgrade:0}}
function itemRating(item){return item?Object.values(item.stats).reduce((a,b)=>a+b,0)+(item.upgrade||0)*2:0}
function dropItem(enemyType){const slots=Object.keys(SLOT_NAMES),slot=slots[Math.floor(Math.random()*slots.length)],item=makeItem(slot,enemyType==='boss'?Math.min(4,Math.floor(Math.random()*4)+2):undefined);state.inventory.unshift(item);state.inventory=state.inventory.slice(0,80);$('#gear-dot').classList.add('show');feedback(`${item.rarity.toUpperCase()} DROP!`);notify(`${item.rarity} ${SLOT_NAMES[slot]} found`);soundEffect(760,.22)}
function hurtEnemy(enemy,amount,critical=false){if(!enemy||enemy.userData.dead)return;const d=enemy.userData;d.hp=Math.max(0,d.hp-amount);spawnHit(enemy.position,critical?0xffcd6e:0xd9d3c4);if(critical)feedback(`CRITICAL · ${amount}`);if(d.hp<=0)defeatEnemy(enemy);updateHud()}
function defeatEnemy(enemy){const d=enemy.userData;if(d.dead)return;d.dead=true;const def=ENEMY_DEFS[d.type];state.kills++;state.gold+=def.gold;gainXp(def.xp);if(d.type==='boss'){state.bossKills++;state.completedDungeons=[...new Set([...state.completedDungeons,'Forgotten Catacombs'])];state.gold+=80;$('#boss-warning').classList.add('show');setTimeout(()=>$('#boss-warning').classList.remove('show'),2500);notify('CATACOMBS CLEARED · BOSS REWARD +80 GOLD');}if(Math.random()<def.drop)dropItem(d.type);createBurst(enemy.position,d.type==='boss'?0xeac46e:0xc2b7a0);worldScene.remove(enemy);enemyList=enemyList.filter(e=>e!==enemy);enemyMeshes=enemyMeshes.filter(e=>e!==enemy);if(target===enemy)target=null;updateHud();if(enemyList.length===0){state.floor=state.floor>=4?1:state.floor+1;if(d.type==='boss')state.floor=1;enemySpawnTimer=2.2;$('#wave-label').textContent=`FLOOR ${String(state.floor).padStart(2,'0')} · ${state.bossKills?'THE KINGDOM STIRS':'THE AWAKENING'}`;}save()}
function currentEnemies(){return enemyList.filter(e=>!e.userData.dead)}
function selectTarget(){const list=currentEnemies();if(!list.length){target=null;return}target=list.reduce((a,b)=>a.position.distanceToSquared(player.position)<b.position.distanceToSquared(player.position)?a:b)}
function spawnWave(){if(currentEnemies().length)return;if(state.floor>=4){makeEnemy('boss');}else{const types=state.floor===1?['skeleton','goblin']:state.floor===2?['goblin','dark','skeleton']:['dark','skeleton','goblin'];for(let i=0;i<2;i++)makeEnemy(types[Math.floor(Math.random()*types.length)]);}selectTarget();updateHud()}

