function spawnHit(pos,color){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.12,0),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.copy(pos).add(new THREE.Vector3(0,1.15,0));worldScene.add(m);effects.push({mesh:m,life:.27,max:.27,kind:'hit'})}
