 if(!currentEnemies().length){enemySpawnTimer-=dt;if(enemySpawnTimer<=0)spawnWave()}else if(!target||target.userData.dead)selectTarget();
 const d=target?.userData;if(d&&!d.dead){const diff=new THREE.Vector3(target.position.x-player.position.x,0,target.position.z-player.position.z),dist=diff.length();if(dist>1.45){diff.normalize();const speed=2.12;player.position.addScaledVector(diff,Math.min(speed*dt,dist-1.25));player.rotation.y=Math.atan2(diff.x,diff.z)+Math.PI;const gait=t*9;player.userData.legs.forEach((leg,i)=>leg.rotation.x=Math.sin(gait+i*Math.PI)*.34);player.userData.arms[0].rotation.x=Math.sin(gait)*.22;}else{player.rotation.y=Math.atan2(diff.x,diff.z)+Math.PI;attackTimer-=dt;if(attackTimer<=0){attackTimer=1.35;player.userData.attack=.34;const crit=Math.random()*100<critChance();hurtEnemy(target,Math.floor(attackPower()*(crit?1.8:1)),crit);soundEffect(crit?190:135,.07)}}
