function resize3D(){if(!renderer||!camera)return;camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<600?54:49;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))}

function panelHead(kicker,title){return `<header class="panel-head"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div><button class="close-button" data-action="close" aria-label="Close">×</button></header>`}
function openPanel(name){$('#panel-wrap').classList.add('open');$('#panel-wrap').setAttribute('aria-hidden','false');renderPanel(name)}
function closePanel(){$('#panel-wrap').classList.remove('open');$('#panel-wrap').setAttribute('aria-hidden','true')}
function renderPanel(name){const panel=$('#game-panel');let body='';let kicker='HUNTER DOSSIER',title='THE AWAKENED';
 if(name==='hero'){
  title='Hunter Profile';const cls=state.classKey?CLASS_PATHS[state.classKey][Math.min(2,Math.floor((state.level-1)/15))]: 'Unclassified Hunter';
  body=`<div class="stat-grid"><div class="stat-card"><small>Hunter level</small><strong>${state.level}</strong></div><div class="stat-card"><small>Rank</small><strong>◈ ${state.rank}</strong></div><div class="stat-card"><small>Class</small><strong style="font-size:13px">${cls}</strong></div><div class="stat-card"><small>Gold</small><strong>✦ ${formatNum(state.gold)}</strong></div><div class="stat-card"><small>Enemies slain</small><strong>${state.kills}</strong></div><div class="stat-card"><small>Boss victories</small><strong>${state.bossKills}</strong></div></div><h3 class="section-title">ATTRIBUTES <span style="color:#bda064;font:10px Inter">${state.attributePoints} points</span></h3>${Object.entries(state.attributes).map(([key,val])=>`<div class="attribute-row"><div class="attribute-name">${key[0].toUpperCase()+key.slice(1)}<small>${key==='strength'?'Attack power':key==='agility'?'Critical chance':key==='vitality'?'Maximum health & defense':'Arcane potential'}</small></div><div class="inline-actions"><span class="attribute-value">${val}</span><button class="small-button" data-action="attribute" data-key="${key}" ${state.attributePoints<=0?'disabled':''}>＋</button></div></div>`).join('')}<h3 class="section-title">COMBAT RATING</h3><div class="stat-grid"><div class="stat-card"><small>Maximum health</small><strong>${formatNum(maxHp())}</strong></div><div class="stat-card"><small>Attack damage</small><strong>${attackPower()}</strong></div><div class="stat-card"><small>Defense</small><strong>${defense()}</strong></div><div class="stat-card"><small>Critical chance</small><strong>${critChance().toFixed(1)}%</strong></div><div class="stat-card"><small>Critical damage</small><strong>180%</strong></div><div class="stat-card"><small>Attribute points</small><strong>${state.attributePoints}</strong></div></div><div class="note">Your hunter fights automatically. Grow stronger here, equip drops, and activate combat skills from the four buttons on the battlefield.</div>`;
 }else if(name==='gear'){
  kicker='ARSENAL';title='Equipment & Inventory';body=`<div class="eyebrow">EQUIPPED · BONUSES APPLY TO YOUR HUNTER</div>${Object.entries(SLOT_NAMES).map(([slot,label])=>{const it=state.gear[slot];return `<div class="equipment-row"><span class="attribute-name">${GEAR_ICONS[slot]} &nbsp;${label}</span>${it?`<span class="${rarityClass(it)}" style="font-size:10px;font-weight:700">${it.name} <small style="color:#aaa">+${itemRating(it)}</small></span>`:'<span style="color:#767670;font-size:10px">Empty slot</span>'}</div>`}).join('')}<h3 class="section-title">BAG · ${state.inventory.length} / 80</h3>${state.inventory.length?state.inventory.map((it,i)=>itemMarkup(it,i)).join(''):'<div class="empty-state">No equipment yet.<br>Defeat monsters for a chance at loot.</div>'}<div class="note">Tap EQUIP to compare an item with your current slot. Upgrade cost is based on item rarity and level.</div>`;
 }else if(name==='skills'){
  kicker='HUNTER ARTS';title='Skills';const skills=[['strike','Powerful Strike','A focused overhead blow. Deals 255% attack damage to your target.','8 sec cooldown'],['sweep','Soul Sweep','A spectral arc that damages every nearby enemy.','12 sec cooldown'],['heal','Dark Heal','Draws vitality from the shadows to restore 32% max health.','18 sec cooldown'],['ultimate','Shadow Burst','Unleash a devastating wave against all foes nearby.','40 sec cooldown']];body=`<div class="skill-grid">${skills.map(([key,label,desc,cool])=>`<div class="skill-card"><h3>${label} <span style="color:#c6a365">Lv ${state.skillLevels[key]}</span></h3><p>${desc}</p><small>${cool}</small><button class="small-button" data-action="upgrade-skill" data-key="${key}" style="display:block;margin-top:8px">UPGRADE · ${skillCost(key)}G</button></div>`).join('')}</div><div class="note">Skills are activated with the large touchscreen buttons during combat. Upgrade costs increase each skill's effectiveness.</div>`;
